#!/usr/bin/env python3
"""Render current Part 1 state and local handover after the population stop."""
import argparse,json,subprocess
from pathlib import Path
from experiment import BASE,EXPERIMENT,REPO,SCOPE

def read(path):return json.loads((EXPERIMENT/path).read_text())
def git(repo,*args):return subprocess.check_output(['git','-C',str(repo),*args],text=True).strip()
def report():
 b=read('results/developer-baseline.json');c=read('results/commits-check.json');f=read('results/classpath-fetch.json');cov=read('results/coverage-smoke.json');p=read('population/population-enumeration.json')
 state={'status':p['status'],'stopped_at_step':4,'completed':['original Steps 1-2','addendum Decision 1: classpath and released coverage tools','addendum Decision 2: extended commit range'],'developer_denominator':b['developer_denominator'],'selected_commits':c['selected_rows'],'scope_changing_commits':c['selected_scope_changes'],'population_eligible_methods':p['total'],'population_classes':len(p['per_class']),'missing_required_original_methods':[m['id'] for m in p['missing_required_original_methods']],'dataset_prepare_run':False,'overload_id_uniqueness':'not checked; fixed decisions conflict before generation','persistent_container_override':'not started after mandatory population stop','llm_calls':0,'pushes':0,'first_attempt':{'commit':'05e849ed','stop':'Step 3 exact EvoSuite/JaCoCo snapshot resolution failures','resolved_by':'user addendum Decision 1'}}
 (EXPERIMENT/'results/part1-status.json').write_text(json.dumps(state,indent=2)+'\n')
 lines=['# Part 1 status after addendum','','The classpath and commit-range decisions are implemented. Part 1 stops during Step 4 because the fixed population requirements conflict: private methods are excluded, but the original scoped dataset contains private focal methods that are required to be included. No DatasetPrepare run or persistent compose override was performed after this stop.','','All numbers: `python3 experiments/ktester-commit-survival/tools/report_part1.py`, reading results/commits-check.json, results/developer-baseline.json, results/classpath-fetch.json, results/coverage-smoke.json and population/population-enumeration.json. Their measurement invocations are recorded in the corresponding reports.','',f"- Range: {c['selected_rows']} first-parent commits; {c['selected_src_changes']} change src/main; {c['selected_scope_changes']} change scoped source files.",f"- Developer denominator unchanged: {b['developer_denominator']} methods pass all runs, from {b['scope_methods']} scoped methods. The skipped Base64Test.testCodec265 remains excluded.",f"- Current artifact set: {f['resolved']}/{f['requested']} resolved with recorded SHA-256. EvoSuite removed; coverage uses released JaCoCo. The XML has {cov['line_entries']} Md5Crypt.java line entries and {cov['counters']['LINE']['covered']} covered lines.",f"- Eligible population: {p['total']} methods in {len(p['per_class'])} classes, within the required bound. Original scoped focal methods missing under the non-private rule: {len(p['missing_required_original_methods'])}.",f"- Overload groups enumerated: {p['overload_group_count']}. Generated-ID uniqueness and original-entry round trips were not run because the earlier fixed-decision conflict requires stopping.",'','## Conflicting original focal methods','']
 for m in p['missing_required_original_methods']:
  d=m['declaration_at_t'];lines.append(f"- `{m['class']}.{m['method-name']}`: {d['visibility']} at upstream line {d['line']} (Spoon evidence in population-enumeration.json).")
 lines+=['','The candidates and enumeration JSON are committed as diagnostic evidence in both repositories. No dataset_meta.json or dataset_info.json exists for this population. No source/settings/index changes, model calls, generated tests, or pushes occurred. Temporary compose run -v mounts preserve the original cache and mounts; Step 5 persistent wiring was not reached.','','## First attempt','','The initial run stopped at Step 3 after repeated Maven Central failures for EvoSuite and JaCoCo snapshots (commit 05e849ed). The user addendum excluded EvoSuite, selected released coverage jars, and extended the range. Those original blockers are resolved.','','TODO (Gary): Reconcile the requirement to include the original private focal methods with the non-private population rule. DatasetPrepare itself also rejects private methods; do not silently patch it or drop required methods. Then resume metadata generation, overload-ID validation and Step 5 wiring.']
 (EXPERIMENT/'results/part1-status.md').write_text('\n'.join(lines)+'\n')

def handover(kt):
 b=read('results/developer-baseline.json');c=read('results/commits-check.json');f=read('results/classpath-fetch.json');cov=read('results/coverage-smoke.json');p=read('population/population-enumeration.json');artifacts=read('tools/classpath-artifacts.json')
 lines=['# Part 1 handover after addendum','','Part 1 remains incomplete at Step 4. Both addendum decisions are complete, but two existing required focal methods are private and cannot belong to the specified non-private population. The instruction says to stop if a fixed decision is impossible; no metadata generation or later persistent container wiring was attempted.','','All numbers and Git identities below: `python3 experiments/ktester-commit-survival/tools/report_part1.py --handover --kt '+str(kt)+'`. Measurements come from the linked JSON/report files; repository identities use git branch --show-current and git rev-parse HEAD.','','## Final repositories','',f"- commons-codec: `{git(REPO,'branch','--show-current')}` at `{git(REPO,'rev-parse','HEAD')}`.",f"- KTester: `{git(kt,'branch','--show-current')}` at `{git(kt,'rev-parse','HEAD')}`.",'- Neither repository was pushed; new commits have the required Codex co-author trailer.','- KTester additions are the population diagnostic directory under data/commit-survival/commons-codec/ and docker/part1_codec_population.py. The authors’ dataset_info.json, snapshot, code/settings.py, and project index were not modified.','- Commons-codec artifacts are under experiments/ktester-commit-survival/. The root ignore rules from the first attempt keep work/ and this handover local. Pre-existing KTester untracked instruction documents and Claude outputs/ remain untouched.','','## Completed addendum decisions','',f"All {f['resolved']}/{f['requested']} approved artifacts resolved. Runtime and coverage roles are separate in tools/classpath-artifacts.json. EvoSuite is removed; JaCoCo is the explicitly authorized release. Coverage jars do not appear in compile/run classpaths. The Md5Crypt.java XML has {cov['line_entries']} line entries and {cov['counters']['LINE']['covered']} covered lines (results/coverage-smoke.json).",'',f"The range has {c['selected_rows']} commits, {c['selected_src_changes']} changing src/main and {c['selected_scope_changes']} changing scope files, ending at {c['last_selected']['sha']} ({c['last_selected']['date']}). All links were verified (results/commits-check.json)."]
 for tag in c['release_tags']:lines.append(f"- {tag['tag']}: index {tag['index']}, {tag['sha']}.")
 lines+=['','## Developer baseline unchanged','',f"Denominator: **{b['developer_denominator']}** passing methods, from {b['scope_methods']} scoped methods. Base64Test.testCodec265 is skipped in every run. Whole-suite reference: {b['whole_methods']} methods, {b['whole_pass_all']} passing every run. Sources: dev/dev-denominator.csv, dev/dev-methods-all.csv, results/developer-baseline.json. Frozen sources are in dev/src-test-t/.",'','| Run | Cases | Failures | Errors | Skipped | Seconds |','|---:|---:|---:|---:|---:|---:|']
 for i,r in enumerate(b['runs'],1):
  t=r['totals'];lines.append(f"| {i} | {t['tests']} | {t['failures']} | {t['errors']} | {t['skipped']} | {r['seconds']} |")
 lines+=['','## Population stop','',f"Spoon enumerated {p['total']} eligible methods; the result is inside the required interval. Only outer-class declarations were included; constructors, private, abstract and bodyless methods were excluded. The driver byte-verified scoped upstream source files against t, and manually cross-checked Sha2Crypt declarations. See population/README.md, candidates.csv and population-enumeration.json.",'','| Class | Eligible methods |','|---|---:|']
 for cls,n in p['per_class'].items():lines.append(f'| {cls} | {n} |')
 lines+=['',f"The original scoped dataset contains {p['scoped_original_count']} methods; {len(p['missing_required_original_methods'])} cannot satisfy the non-private rule:",'']
 for m in p['missing_required_original_methods']:lines.append('- `'+m['class']+'.'+m['method-name']+'` — private at t.')
 lines+=['',f"Pre-generation overload groups: {p['overload_group_count']}, containing {p['methods_in_overload_groups']} methods. Generated-ID uniqueness: not run. DatasetPrepare: not run. Author-entry field comparison: not run. No dataset_meta.json or dataset_info.json was produced; the committed candidate artifacts are diagnostic only.",'','## Current coordinates and exact coverage commands','']
 for a in artifacts:lines.append('- `'+a['coordinate']+'`'+(' classifier='+a['classifier'] if a['classifier'] else '')+' — '+a['role']+'.')
 lines+=['','From /repo/experiments/ktester-commit-survival inside the container (exact successful compile/agent/report commands from results/coverage-smoke.json):','','```sh',*[r['shell_command'] for r in cov['runs']],'```','','The smoke launcher exits nonzero for permitted assertion failures; it executes the tests and writes the verified nonzero coverage. Public logs are under results/coverage-smoke-*.txt; the authored source and XML/exec remain in ignored work/smoke/.','','## First attempt','','The first attempt ended at Step 3, commons-codec commit 05e849ed, because the exact supplied EvoSuite and JaCoCo snapshot artifacts failed Central resolution twice. The addendum explicitly resolved these dependencies and extended the range. Historical logs remain available; they do not represent current dependency failures. The initial attempt also hit a cached tree-sitter import issue during an optional audit; the current required population enumeration instead uses the permitted bundled Spoon parser.','','## Remaining work','','The only current blocker is the conflict among fixed population requirements. The driver neither changed method visibility nor omitted required dataset methods silently. The authors’ source was not used for DatasetPrepare because that stage was not entered; when resumed, it must read the authors’ snapshot via the prescribed symlink. The project index remains the authors’ index. Step 5’s persistent compose override was not created after the mandatory stop.','','TODO (Gary): Resolve the private-method inclusion conflict explicitly, accounting for DatasetPrepare’s own private-method rejection. Then resume metadata generation and the mandatory collision/missing-entry checks without changing the fixed classes or developer denominator.','TODO (Gary): After the population step succeeds, add and verify the Step 5 compose override, then refresh this handover.']
 out=EXPERIMENT/'docs/handover-part1.md';out.write_text('\n'.join(lines)+'\n');print(out)
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--handover',action='store_true');ap.add_argument('--kt',type=Path);args=ap.parse_args()
 if args.handover:
  if args.kt is None:ap.error('--kt required')
  handover(args.kt)
 else:report()
